const W=[["Emergency",28,30],["Intensive care",18,20],["Cardiology",36,42],["Maternity",29,40],["Paediatrics",24,32],["Surgery",58,64],["General medicine",96,110]];
document.getElementById('wards').innerHTML=W.map(w=>{const p=Math.round(w[1]/w[2]*100),c=p>=90?'#DC2626':p>=80?'#EA580C':'#0E7490';return `<div class="ward"><span>${w[0]}</span><div class="t"><i style="width:${p}%;background:${c}"></i></div><b>${w[1]}/${w[2]}</b></div>`}).join('');
const ER=[["#DC2626","Patient A-1041","Chest pain, age 64",3],["#EA580C","Patient A-1043","Breathing difficulty, age 7",11],["#CA8A04","Patient A-1039","Suspected broken wrist, age 32",42],["#CA8A04","Patient A-1044","High fever, age 51",18],["#15803D","Patient A-1037","Minor cut to hand, age 26",64]];
let t0=Date.now();function er(){const m=Math.floor((Date.now()-t0)/60000);document.getElementById('er').innerHTML=ER.map(e=>`<li><i style="background:${e[0]}" aria-hidden="true"></i><div><b>${e[1]}</b><small>${e[2]}</small></div><div class="w">${e[3]+m} min<small>waiting</small></div></li>`).join('')}er();setInterval(er,30000);
const A=[["08:30","Maria Gonzalez","Cardiology","Dr. Osei","done"],["09:00","James Wu","Orthopaedics","Dr. Patel","done"],["09:30","Aisha Bello","Paediatrics","Dr. Mori","in"],["10:00","Peter Novak","Dermatology","Dr. Klein","waiting"],["10:15","Sara Lindholm","Cardiology","Dr. Osei","waiting"],["10:30","Omar Farouk","Neurology","Dr. Grant","missed"]];
const S={waiting:"Waiting",in:"In consultation",done:"Done",missed:"Missed"};
function ap(f){document.getElementById('appts').innerHTML=A.filter(a=>f==='all'||a[4]===f).map(a=>`<tr><td><b>${a[0]}</b></td><td>${a[1]}</td><td>${a[2]}</td><td>${a[3]}</td><td><span class="chip s-${a[4]}">${S[a[4]]}</span></td></tr>`).join('')||'<tr><td colspan="5">No appointments in this view.</td></tr>'}
document.querySelectorAll('#flt button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('#flt button').forEach(x=>x.setAttribute('aria-pressed',x===b));ap(b.dataset.f)}));ap('all');
function adm(){const s=document.getElementById('adm'),w=s.clientWidth||380,h=220,pl=30,pb=22,v=[52,61,48,57,66,71,58],L=["Wed","Thu","Fri","Sat","Sun","Mon","Tue"],mx=80;
const X=i=>pl+i/(v.length-1)*(w-pl-12),Y=x=>h-pb-x/mx*(h-pb-10);let o='';
[0,40,80].forEach(t=>{o+=`<line x1="${pl}" x2="${w-12}" y1="${Y(t)}" y2="${Y(t)}" stroke="#E2E8F0"/><text x="${pl-6}" y="${Y(t)+4}" text-anchor="end" font-size="11" fill="#64748B">${t}</text>`});
const d=v.map((x,i)=>(i?'L':'M')+X(i)+' '+Y(x)).join(' ');
o+=`<path d="${d} L${X(6)} ${h-pb} L${pl} ${h-pb}Z" fill="#0E7490" opacity=".1"/><path d="${d}" fill="none" stroke="#0E7490" stroke-width="3"/>`;
v.forEach((x,i)=>{o+=`<circle cx="${X(i)}" cy="${Y(x)}" r="3.5" fill="#fff" stroke="#0E7490" stroke-width="2"/><text x="${X(i)}" y="${h-5}" text-anchor="middle" font-size="11" fill="#64748B">${L[i]}</text>`});
s.setAttribute('viewBox',`0 0 ${w} ${h}`);s.innerHTML=o}adm();window.addEventListener('resize',adm);
(()=>{const b=document.querySelector('.burger'),m=document.getElementById('menu'),y=document.getElementById('yr');
if(b&&m){b.addEventListener('click',()=>{const o=m.classList.toggle('open');b.setAttribute('aria-expanded',o)});
m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded',false)}))}
if(y)y.textContent=new Date().getFullYear()})();
